import random

symbol_counts = {"A": 2, "B": 2, "C": 2, "D": 2}

def get_slot_machine_spin(symbol_counts, columns=3, rows=3):
    # Build a list that contains each symbol as many times as its count
    symbols = []
    for symbol, count in symbol_counts.items():
        symbols.extend([symbol] * count)
    spin = []
    for _ in range(columns):
        column = []
        while len(column) < rows:
            choice = random.choice(symbols)
            if choice not in column:
                column.append(choice)
        spin.append(column)
    return spin

if __name__ == "__main__":
    result = get_slot_machine_spin(symbol_counts)
    for col in result:
        print(col)

